using System;using System.IO;using System.Drawing;using Musikbox;
class PrepareFixture57 {static void Main(){string path=Path.GetFullPath("verify/fixture/source.mp3"),image=Path.GetFullPath("verify/fixture/cover.png");using(var bmp=new Bitmap(32,32)){using(var g=Graphics.FromImage(bmp))g.Clear(Color.Purple);bmp.Save(image,System.Drawing.Imaging.ImageFormat.Png);}var song=MediaMetadata.Read(path);song.Artwork=image;MediaMetadata.Write(path,song,song.Album);using(var file=TagLib.File.Create(path)){var tag=(TagLib.Id3v2.Tag)file.GetTag(TagLib.TagTypes.Id3v2,true);TagLib.Id3v2.UserTextInformationFrame.Get(tag,"CUSTOM_TEST",true).Text=new[]{"Erhalten äöü"};file.Save();}Console.WriteLine("Fixture mit eingebettetem Cover und freiem Tag vorbereitet");}}
